use data::*;

#[cfg(test)]
use std::sync::Mutex;

#[cfg(not(test))]
extern "C" {
  fn get_battery_evidence(value: *mut Drone_Lifecycle_Governor::Battery_Evidence) -> bool;
  fn get_decision_disposition(value: *mut Drone_Lifecycle_Governor::Decision_Disposition) -> bool;
  fn put_pilot_notice(value: *mut Drone_Lifecycle_Governor::Pilot_Notice) -> bool;
}

pub fn unsafe_get_battery_evidence() -> Drone_Lifecycle_Governor::Battery_Evidence
{
  unsafe {
    let value: *mut Drone_Lifecycle_Governor::Battery_Evidence = &mut Drone_Lifecycle_Governor::Battery_Evidence::default();
    get_battery_evidence(value);
    return *value;
  }
}

pub fn unsafe_get_decision_disposition() -> Drone_Lifecycle_Governor::Decision_Disposition
{
  unsafe {
    let value: *mut Drone_Lifecycle_Governor::Decision_Disposition = &mut Drone_Lifecycle_Governor::Decision_Disposition::default();
    get_decision_disposition(value);
    return *value;
  }
}

pub fn unsafe_put_pilot_notice(value: &Drone_Lifecycle_Governor::Pilot_Notice) -> bool
{
  unsafe {
    return put_pilot_notice(value as *const Drone_Lifecycle_Governor::Pilot_Notice as *mut Drone_Lifecycle_Governor::Pilot_Notice);
  }
}

//////////////////////////////////////////////////////////////////////////////////
// Testing Versions
//////////////////////////////////////////////////////////////////////////////////

#[cfg(test)]
lazy_static::lazy_static! {
  // simulate the global C variables that point to the microkit shared memory regions.  In a full
  // microkit system we would be able to mutate the shared memory for out ports since they're r/w,
  // but we couldn't do that for in ports since they are read-only
  pub static ref IN_battery_evidence: Mutex<Option<Drone_Lifecycle_Governor::Battery_Evidence>> = Mutex::new(None);
  pub static ref IN_decision_disposition: Mutex<Option<Drone_Lifecycle_Governor::Decision_Disposition>> = Mutex::new(None);
  pub static ref OUT_pilot_notice: Mutex<Option<Drone_Lifecycle_Governor::Pilot_Notice>> = Mutex::new(None);
}

#[cfg(test)]
pub fn initialize_test_globals() {
  unsafe {
    *IN_battery_evidence.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *IN_decision_disposition.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_pilot_notice.lock().unwrap_or_else(|e| e.into_inner()) = None;
  }
}

#[cfg(test)]
pub fn get_battery_evidence(value: *mut Drone_Lifecycle_Governor::Battery_Evidence) -> bool
{
  unsafe {
    let guard = IN_battery_evidence.lock().unwrap_or_else(|e| e.into_inner());
    *value = guard.expect("Not expecting None");
    true
  }
}

#[cfg(test)]
pub fn get_decision_disposition(value: *mut Drone_Lifecycle_Governor::Decision_Disposition) -> bool
{
  unsafe {
    let guard = IN_decision_disposition.lock().unwrap_or_else(|e| e.into_inner());
    *value = guard.expect("Not expecting None");
    true
  }
}

#[cfg(test)]
pub fn put_pilot_notice(value: *mut Drone_Lifecycle_Governor::Pilot_Notice) -> bool
{
  unsafe {
    *OUT_pilot_notice.lock().unwrap_or_else(|e| e.into_inner()) = Some(*value);
    return true;
  }
}
